-- Requirement: Calculate total bookings and total booking revenue generated by each route.

USE modern_db_lab;
SELECT r.route_name, COUNT(b.booking_id) AS total_bookings, COALESCE(SUM(b.journey_fare),0) AS total_booking_revenue
FROM ROUTE r
LEFT JOIN TRIP t ON t.route_id = r.route_id
LEFT JOIN BOOKING b ON b.trip_id = t.trip_id AND b.booking_status <> 'CANCELLED'
GROUP BY r.route_id, r.route_name
ORDER BY total_booking_revenue DESC;
